
.intro-screen {
  position: relative;
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
  background: #0c0a10;
  cursor: pointer;
  user-select: none;
}

.frame-layer {
  position: absolute;
  inset: 0;
}

.layer-enter-active {
  transition: opacity 0.2s ease;
}

.layer-leave-active {
  transition: opacity 0.3s ease;
}

.layer-enter-from,
.layer-leave-to {
  opacity: 0;
}

/* —— 面部特写推镜 —— */

.closeup-img {
  position: absolute;
  left: 50%;
  top: 50%;
  max-width: none;
  animation-name: kb-push;
  animation-timing-function: cubic-bezier(0.25, 0.6, 0.35, 1);
  animation-fill-mode: both;
}

@keyframes kb-push {
  from {
    transform: var(--kb-from);
  }
  to {
    transform: var(--kb-to);
  }
}

/* —— 完整图 —— */

.full-wrap {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0c0a10;

  /* 收束帧：虹膜展开（⑤⑥⑧） */
  &.is-converge {
    animation: converge 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
  }
}

@keyframes converge {
  from {
    clip-path: circle(7% at 50% 50%);
  }
  to {
    clip-path: circle(142% at 50% 50%);
  }
}

.full-img {
  position: relative;
  width: 100%;
  height: 100%;
  /* 竖屏可读性优先：整图 contain（四宫格必须读全），空边由 .full-fill 模糊同源图填充 */
  object-fit: contain;
  animation: full-settle 2.4s ease-out both;
}

@keyframes full-settle {
  from {
    transform: scale(1.06);
  }
  to {
    transform: scale(1);
  }
}

/* 空边填充：同源模糊放大副本 */
.full-fill {
  position: absolute;
  inset: -6%;
  width: 112%;
  height: 112%;
  object-fit: cover;
  filter: blur(34px) brightness(0.42);
}

/* —— 「走出创伤」长转场：推近右下角玩具熊的暖光点，画面渐白，情绪由暗入明 —— */

.heal-veil {
  position: absolute;
  inset: 0;
  background: #fdfdfe;
  opacity: 0;
  pointer-events: none;
}

.is-healing {
  .full-img,
  .full-fill {
    animation: heal-zoom 2.8s cubic-bezier(0.45, 0, 0.8, 0.4) both;
    transform-origin: 75% 72%;
  }

  .heal-veil {
    animation: heal-whiten 2.8s ease-in both;
  }
}

@keyframes heal-zoom {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(2.6);
  }
}

@keyframes heal-whiten {
  0% {
    opacity: 0;
  }
  45% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

.skip-hint {
  position: absolute;
  right: 18px;
  bottom: 16px;
  z-index: 5;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  letter-spacing: 2px;
  color: rgba(255, 255, 255, 0.5);
  animation: hint-in 0.8s ease 1.2s both;
}

@keyframes hint-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* 收束白幕：序奏结束 → 白场 → 标题屏 */
.outro-veil {
  position: absolute;
  inset: 0;
  z-index: 6;
  background: #fdfdfe;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.6s ease;

  &.is-on {
    opacity: 1;
  }
}

/* 减弱动态：脚本侧已全部改走完整图路径，此处关掉收束/推进动画 */
@media (prefers-reduced-motion: reduce) {
  .full-wrap.is-converge,
  .full-img {
    animation: none;
  }
}
