
.gallery-screen {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 32px 0 40px;
  overflow-x: hidden;
}

.title-row {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}

.screen-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 400;
  letter-spacing: 4px;
  color: var(--c-text);
  margin-bottom: 8px;
}

.admin-toggle {
  position: absolute;
  right: 16px;
  top: 0;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--c-surface);
  box-shadow: var(--shadow-card);
  color: var(--c-text-muted);
  font-size: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    color 0.15s ease,
    transform 0.15s ease;

  &:hover {
    color: var(--c-primary-strong);
    transform: rotate(30deg);
  }

  &.is-on {
    color: var(--c-primary-strong);
    transform: none;
  }
}

.gallery-hint {
  font-size: 13px;
  color: var(--c-text-muted);
  margin-bottom: 24px;
  padding: 0 16px;
  text-align: center;
}

/* —— 管理栏 —— */

.admin-bar {
  width: min(92vw, 480px);
  margin-bottom: 18px;
  padding: 12px 16px;
  border-radius: var(--radius-card);
  background: var(--c-surface);
  border: 1px dashed var(--c-border-strong);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.admin-hint {
  font-size: 12px;
  color: var(--c-text-muted);
  line-height: 1.6;

  i {
    color: var(--c-danger);
  }
}

.admin-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.admin-add {
  padding: 10px 22px;
  font-size: 14px;
}

/* —— 放映带 —— */

.film-strip {
  width: 100%;
  background: var(--c-film-bg);
  box-shadow: 0 10px 30px rgba(36, 29, 34, 0.35);
}

.film-holes {
  height: 16px;
  background-image: radial-gradient(circle, var(--c-film-hole) 2.6px, transparent 3.4px);
  background-size: 26px 100%;
  background-repeat: repeat-x;
  background-position: center;
}

.film-clip {
  overflow: hidden;
}

.film-track {
  display: flex;
  gap: 16px;
  width: max-content;
  padding: 12px 16px;
  animation: film-scroll linear infinite;

  &.is-paused {
    animation-play-state: paused;
  }
}

@keyframes film-scroll {
  to {
    transform: translateX(-50%);
  }
}

.film-frame {
  position: relative;
  flex: none;
  width: 220px;
  margin: 0;
  background: var(--c-film-bg-deep);
  border: 1px solid var(--c-film-frame-border);
  border-radius: 6px;
  overflow: hidden;
  cursor: pointer;
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;

  &:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4);
  }
}

.frame-thumb {
  aspect-ratio: 16 / 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.04);

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    user-select: none;
  }

  &.is-placeholder {
    color: var(--c-film-text);
    opacity: 0.55;
    font-size: 12px;

    i {
      font-size: 24px;
    }
  }
}

.frame-label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  color: var(--c-film-text);
  font-size: 11px;
}

.frame-no {
  font-family: var(--font-latin);
  letter-spacing: 1px;
  opacity: 0.6;
}

.frame-title {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.frame-badge {
  flex: none;
  padding: 1px 6px;
  border-radius: 999px;
  background: rgba(229, 138, 165, 0.25);
  color: var(--c-primary-soft);
  font-size: 10px;
}

/* 删除按钮：管理模式显示，二次点击确认 */
.admin-del {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: rgba(20, 14, 18, 0.65);
  color: #fff;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    background 0.15s ease,
    transform 0.15s ease;

  &:hover {
    background: var(--c-danger);
  }

  &.is-armed {
    background: var(--c-danger);
    transform: scale(1.15);
    animation: armed-pulse 0.7s ease-in-out infinite;
  }
}

@keyframes armed-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(217, 95, 95, 0.55);
  }
  50% {
    box-shadow: 0 0 0 7px rgba(217, 95, 95, 0);
  }
}

.footer {
  margin-top: 28px;
  width: 100%;
  max-width: 480px;
  display: flex;
  justify-content: flex-start;
  padding: 0 16px;
}

/* —— 放大灯箱 —— */

.lightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(20, 14, 18, 0.82);
  backdrop-filter: blur(6px);
  padding: 20px;
}

.lightbox-inner {
  position: relative;
  max-width: min(92vw, 960px);
  margin: 0;
  background: var(--c-surface);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5);

  img {
    display: block;
    width: 100%;
    max-height: 72vh;
    object-fit: contain;
    background: #141013;
  }
}

.lightbox-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 16px 14px;
}

.lightbox-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--c-text);
}

.lightbox-caption {
  font-size: 12px;
  color: var(--c-text-muted);
}

.lightbox-close {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 50%;
  background: rgba(20, 14, 18, 0.55);
  color: #fff;
  font-size: 15px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s ease;

  &:hover {
    background: rgba(20, 14, 18, 0.8);
  }
}

/* —— 添加 CG 对话框 —— */

.add-dialog {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(20, 14, 18, 0.72);
  backdrop-filter: blur(6px);
  padding: 20px;
}

.add-card {
  width: min(92vw, 420px);
  padding: 22px 20px;
  border-radius: var(--radius-card);
  background: var(--c-surface);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.add-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--c-text);

  i {
    color: var(--c-primary);
    margin-right: 6px;
  }
}

.add-picker {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 140px;
  border: 2px dashed var(--c-border-strong);
  border-radius: 12px;
  color: var(--c-text-muted);
  font-size: 13px;
  cursor: pointer;
  overflow: hidden;
  transition: border-color 0.15s ease;

  &:hover {
    border-color: var(--c-primary);
  }

  input[type='file'] {
    display: none;
  }

  i {
    font-size: 28px;
    color: var(--c-primary);
  }

  &.has-image {
    border-style: solid;
    min-height: 0;
  }

  img {
    width: 100%;
    max-height: 220px;
    object-fit: contain;
    background: var(--c-surface-muted);
  }
}

.add-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 13px;
  color: var(--c-text-muted);

  input,
  textarea {
    padding: 10px 12px;
    border: 1px solid var(--c-border);
    border-radius: 10px;
    background: var(--c-surface-muted);
    font-size: 14px;
    resize: none;

    &:focus {
      outline: none;
      border-color: var(--c-primary);
      background: var(--c-surface);
    }
  }
}

.add-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;

  .btn-primary {
    padding: 10px 26px;
    font-size: 14px;
  }
}

@media (max-width: 480px) {
  .film-frame {
    width: 178px;
  }
}

/* 减少动态偏好：不自动放映，改手动横滑 */
@media (prefers-reduced-motion: reduce) {
  .film-clip {
    overflow-x: auto;
  }

  .film-track {
    animation: none;
  }
}
