
.custom-form {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 32px 16px 40px;
}

.screen-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 400;
  letter-spacing: 4px;
  margin-bottom: 24px;
}

.form-card {
  width: 100%;
  max-width: 480px;
  padding: 22px 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.ai-panel {
  border: 1px solid var(--c-border);
  border-radius: 12px;
  background: var(--c-surface-muted);
  overflow: hidden;

  summary {
    padding: 12px 14px;
    font-size: 14px;
    font-weight: 600;
    color: var(--c-primary-strong);
    cursor: pointer;
    list-style: none;
    user-select: none;

    i {
      margin-right: 6px;
    }
  }
}

.ai-panel-body {
  padding: 0 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.test-btn {
  align-self: flex-start;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 13px;
  color: var(--c-text-muted);
}

.required {
  color: var(--c-danger);
  font-style: normal;
}

.label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

input[type='text'],
input[type='password'],
select,
textarea {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--c-border);
  border-radius: 10px;
  background: var(--c-surface);
  font-size: 14px;
  outline: none;
  transition: border-color 0.15s ease;

  &:focus {
    border-color: var(--c-primary);
  }
}

textarea {
  resize: vertical;
  line-height: 1.7;
}

.gender-group {
  display: flex;
  gap: 10px;
}

.gender-option {
  flex: 1;

  input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
  }

  span {
    display: block;
    text-align: center;
    padding: 9px 0;
    border: 1px solid var(--c-border);
    border-radius: 10px;
    font-size: 14px;
    color: var(--c-text-muted);
    cursor: pointer;
    transition:
      border-color 0.15s ease,
      background 0.15s ease,
      color 0.15s ease;
  }

  input:checked + span {
    border-color: var(--c-primary);
    background: var(--c-primary-soft);
    color: var(--c-primary-strong);
    font-weight: 600;
  }
}

.ai-fill-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 12px;
  border-radius: var(--radius-button);
  border: 1px solid var(--c-accent-soft);
  background: var(--c-surface);
  color: var(--c-accent);
  font-size: 12px;
  transition:
    background 0.15s ease,
    opacity 0.15s ease;

  &:hover:not(:disabled) {
    background: var(--c-accent-soft);
  }

  &:disabled {
    opacity: 0.6;
    cursor: wait;
  }
}

.actions {
  margin-top: 6px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
