
.opening-root {
  min-height: 100vh;
  min-height: 100dvh;
}

.done-screen {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px 16px;
}

.done-card {
  width: 100%;
  max-width: 480px;
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  text-align: center;
}

.done-icon {
  font-size: 44px;
  color: var(--c-success);
}

.done-title {
  font-size: 20px;
  font-weight: 800;
}

.done-hint {
  font-size: 13px;
  color: var(--c-text-muted);
}

.done-summary {
  width: 100%;
  padding: 14px;
  border-radius: 10px;
  background: var(--c-surface-muted);
  border: 1px solid var(--c-border);
  font-size: 12px;
  line-height: 1.7;
  text-align: left;
  white-space: pre-wrap;
  word-break: break-all;
  color: var(--c-text-muted);
}

.toast-container {
  position: fixed;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  pointer-events: none;
  width: min(92vw, 420px);
}

.toast {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border-radius: var(--radius-button);
  background: var(--c-surface);
  box-shadow: var(--shadow-float);
  font-size: 13px;
  color: var(--c-text);
  border: 1px solid var(--c-border);

  &.toast-success i {
    color: var(--c-success);
  }

  &.toast-error i {
    color: var(--c-danger);
  }

  &.toast-info i {
    color: var(--c-primary);
  }
}

.toast-enter-active,
.toast-leave-active {
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}

.toast-enter-from,
.toast-leave-to {
  opacity: 0;
  transform: translateY(-8px);
}
